const crypto = require('crypto');
const input = $input.all()[0].json;

// On-demand: the user's prompt is authoritative. Send it to the prompt-composer
// agent (Claude Sonnet) to refine into a photographic English fal.ai prompt that
// keeps the user's subject as the hero and layers the brand visual identity.
const userPrompt = (input.prompt_en || '').trim();

const payload = {
  flow_id: 'N8N-V01',
  brand_id: input.brand_id || 'MISSING',
  payload: {
    user_prompt: userPrompt || 'product lifestyle photography, clean background, natural lighting',
    user_intent_authoritative: true,
    expected_media_type: input.expected_media_type || input.media_type || input.format_tier || 'image',
    chain_id: input.chain_id || undefined,
  }
};

const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', 'test-webhook-secret-123').update(raw).digest('hex');

return [{ json: {
  url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/prompt-composer',
  body: raw,
  headers: {
    'x-n8n-signature': sig,
    'x-n8n-request-id': crypto.randomUUID(),
    'x-n8n-timestamp': new Date().toISOString(),
  }
}}];

const crypto = require('crypto');
const input = $('Execute Workflow Trigger').first().json;

// Refined prompt from the prompt-composer agent (best-effort; falls back to the raw prompt).
let refinedPrompt = '';
try {
  const comp = $('POST /api/agents/prompt-composer').first().json || {};
  refinedPrompt = ((comp.result && comp.result.composed_prompt_en) || comp.composed_prompt_en || '').trim();
  const AR = /[\u0600-\u06FF]/;
  if (refinedPrompt && AR.test(refinedPrompt)) refinedPrompt = '';
} catch (e) { refinedPrompt = ''; }

if (!input.brand_id) {
  console.warn('[V01] WARNING: brand_id is missing from input:', JSON.stringify(Object.keys(input)));
}

const promptEn = refinedPrompt || (input.prompt_en || '').trim() || 'product lifestyle photography, clean background, natural lighting';

// Map DeepSeek sharp_text_gravity → OverlayLayout.
const GRAVITY_TO_LAYOUT = { south: 'bottom-right', north: 'top-right', center: 'center-right' };
const layout = GRAVITY_TO_LAYOUT[input.sharp_text_gravity];

// SMART MONTH CONVERSION - handles both "June" and "2026-06" formats
function formatMonth(monthInput, yearInput) {
  if (!monthInput) {
    return new Date().toISOString().slice(0, 7);
  }

  // Check if it's already in YYYY-MM format
  if (/^\d{4}-\d{2}$/.test(monthInput)) {
    return monthInput;
  }

  // Check if it's a month name like "June"
  const monthNames = {
    'January': '01', 'February': '02', 'March': '03', 'April': '04',
    'May': '05', 'June': '06', 'July': '07', 'August': '08',
    'September': '09', 'October': '10', 'November': '11', 'December': '12'
  };

  // Try to match the month name (case insensitive)
  const monthName = Object.keys(monthNames).find(
    name => name.toLowerCase() === monthInput.toLowerCase()
  );

  if (monthName) {
    // Use the provided year, or current year if not available
    const year = yearInput || new Date().getFullYear();
    return `${year}-${monthNames[monthName]}`;
  }

  // If it's a number (1-12), format it
  if (/^\d{1,2}$/.test(monthInput)) {
    const year = yearInput || new Date().getFullYear();
    const monthNum = monthInput.padStart(2, '0');
    return `${year}-${monthNum}`;
  }

  // Fallback to current month
  console.warn(`[V01] Unrecognized month format: ${monthInput}, using current month`);
  return new Date().toISOString().slice(0, 7);
}

// Handle palette_hex from various sources
let paletteHex = input.palette_hex || [];
if (input.primary_color_hex && input.primary_color_hex.trim() !== '') {
  paletteHex = [input.primary_color_hex];
}
if (paletteHex.length === 0 && input.brand_color_palette) {
  paletteHex = input.brand_color_palette;
}

// BUG FIX 1: Route video to the async /api/image/generate-video endpoint.
// The sync /api/image/generate blocks up to 450 s for video — ngrok kills at 30 s → 503.
const expectedMediaType = input.expected_media_type || input.media_type || input.format_tier || 'image';
const isVideo = expectedMediaType === 'video';
const endpoint = isVideo
  ? 'https://petition-cupid-buffed.ngrok-free.dev/api/image/generate-video'
  : 'https://petition-cupid-buffed.ngrok-free.dev/api/image/generate';

const payload = {
  flow_id:  'N8N-V01',
  brand_id: input.brand_id  || 'MISSING',
  post_id:  input.post_id   || crypto.randomUUID(),
  payload: {
    prompt_en:           promptEn,
    brand_name_ar:       input.brand_name_ar   || input.brand_name_en || '',
    headline_ar:         input.headline_ar     || input.caption_ar || '',
    dialect:             input.dialect         || 'MSA_formal',
    channel:             input.channel         || 'Instagram',
    objective:           input.objective       || 'awareness',
    first_ever_post:     input.first_ever_post || false,
    confidence_flag:     input.confidence_flag || 'clean',
    cost_constraint:     input.cost_constraint || 'standard',
    palette_hex:         paletteHex,
    month:               formatMonth(input.month, input.year),
    score:               input.score || input.confidence_score || 85,
    expected_media_type: expectedMediaType,
    reference_image_url: input.reference_image_url || undefined,
    chain_id:            input.chain_id        || null,
    chain_context:       input.chain_context   || undefined,
    layout:              layout,
  }
};

const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', 'test-webhook-secret-123').update(raw).digest('hex');

return [{ json: {
  url:      endpoint,
  body:     raw,
  brand_id: input.brand_id,
  post_id:  payload.post_id,
  headers: {
    'x-n8n-signature':  sig,
    'x-n8n-request-id': crypto.randomUUID(),
    'x-n8n-timestamp':  new Date().toISOString(),
  }
}}];

const result = $json.result || $json;
const storageUrl = result.storage_url;
const cleanStorageUrl = result.clean_storage_url || null;
const prepare = $('Prepare image/generate call').first().json;
return [{ json: {
  storage_url:       storageUrl,
  clean_storage_url: cleanStorageUrl,
  keyframe_url:      result.keyframe_url || null,
  brand_id:          prepare.brand_id,
  post_id:           prepare.post_id,
  image_prompt_en:   result.image_prompt_en || null,
  negative_prompt:   result.negative_prompt || null,
  success:           true
}}];

const extracted = $('Extract storage_url').first().json;
return [{ json: { 
  storage_url: extracted.storage_url, 
  clean_storage_url: extracted.clean_storage_url || null, 
  keyframe_url: extracted.keyframe_url || null, 
  image_prompt_en: extracted.image_prompt_en || null, 
  negative_prompt: extracted.negative_prompt || null, 
  success: true 
} }];
